const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};

// 1. Static Webhook Secret Verification
const providedSecret = headers['x-webhook-secret'] || body.secret || '';
const expectedSecret = $env.MANYCHAT_WEBHOOK_SECRET;

if (!expectedSecret || providedSecret !== expectedSecret) {
  throw new Error("Unauthorized webhook call: Invalid X-Webhook-Secret");
}

// 2. Kill Switch Check
const botEnabled = $env.BOT_ENABLED !== 'false';

const subscriberId = String(body.subscriber_id || body.user_id || body.id || '').trim();
const messageText = String(body.message_text || body.text || body.last_input_text || '').trim();
const platform = (body.platform || body.channel || 'instagram').toLowerCase();
const liveChatStatus = body.live_chat_status || 'closed';

if (!subscriberId || !messageText) {
  throw new Error("Malformed webhook payload: missing subscriber_id or message_text.");
}

// Restrict scope to Instagram and Facebook DMs
if (platform !== 'instagram' && platform !== 'facebook') {
  return {
    json: {
      skip: true,
      reason: "Platform out of scope: " + platform
    }
  };
}

// 3. Compute Event Key for Idempotency Claim
const messageId = body.message_id || body.mid || '';
const timeBucket = Math.floor(Date.now() / (60 * 1000)); // 1-minute bucket fallback
const eventKey = messageId ? `mc_${messageId}` : `h_${subscriberId}_${timeBucket}`;

// Compute subscriber hash (never store plain subscriber ID in telemetry)
let hash = 0;
const saltedId = subscriberId + ($env.HASH_SALT || 'salt');
for (let i = 0; i < saltedId.length; i++) {
  hash = ((hash << 5) - hash) + saltedId.charCodeAt(i);
  hash = hash & hash;
}
const subscriberHash = 'sub_' + Math.abs(hash).toString(16);

return {
  json: {
    subscriber_id: subscriberId,
    subscriber_hash: subscriberHash,
    event_key: eventKey,
    message_text: messageText,
    platform: platform,
    live_chat_status: liveChatStatus,
    bot_enabled: botEnabled,
    started_at: Date.now()
  }
};

const event = $('Verify Secret & Extract Event').item.json;
const llmResp = $input.item.json;

// Kill switch check
if (!event.bot_enabled) {
  return {
    json: {
      ...event,
      action: 'disabled',
      intents: [],
      sensitive: false,
      should_reply: false,
      needs_human: true
    }
  };
}

let parsed = { intents: ['other'], sensitive: false, sensitive_reason: '' };
try {
  const rawContent = llmResp.choices[0].message.content;
  parsed = JSON.parse(rawContent);
} catch (e) {
  return {
    json: {
      ...event,
      action: 'invalid_output',
      intents: ['other'],
      sensitive: true,
      should_reply: false,
      needs_human: true
    }
  };
}

const allowlist = new Set(['business_hours', 'shipping_info', 'returns_policy', 'catalog_link']);
const intents = Array.isArray(parsed.intents) ? parsed.intents : [];
const isSensitive = Boolean(parsed.sensitive);

// Decision logic in code:
// Escalate if sensitive, or any intent is 'other'/unlisted, or more than 2 intents detected
const hasUnlisted = intents.length === 0 || intents.some(i => !allowlist.has(i));
const exceedsCount = intents.length > 2;
const shouldEscalate = isSensitive || hasUnlisted || exceedsCount;

// Pre-approved Canned Templates
const TEMPLATES = {
  business_hours: "Our team is available Monday through Friday from 9:00 AM - 6:00 PM (EST). Messages received outside these hours are reviewed the next business day.",
  shipping_info: "Standard domestic orders ship within 3-5 business days. Once your order has dispatched, a tracking link will be emailed to you.",
  returns_policy: "We offer returns on eligible, unopened items within 30 days of delivery. For return authorization, please email support@example.com.",
  catalog_link: "You can explore our full product catalog and current collection directly at https://example.com/shop."
};

const FOOTER = "\n\n—\n🤖 Automated Assistant | Reply 'agent' to speak with our team.";
const HANDOFF_ACK = "Thank you for reaching out. I've flagged your message for our support team so a representative can look into this personally. A team member will follow up with you here shortly." + FOOTER;

let replyText = '';
let templateIds = [];
let action = 'replied';

if (shouldEscalate) {
  replyText = HANDOFF_ACK;
  action = 'escalated';
} else {
  templateIds = intents;
  replyText = intents.map(id => TEMPLATES[id]).join("\n\n") + FOOTER;
}

// Shadow mode handling
const isShadow = $env.SHADOW_MODE === 'true';
if (isShadow && action === 'replied') {
  action = 'shadow';
}

return {
  json: {
    ...event,
    intents: intents,
    sensitive: isSensitive,
    sensitive_reason: parsed.sensitive_reason || '',
    action: action,
    template_ids: templateIds,
    reply_text: replyText,
    should_send_reply: !isShadow && action === 'replied',
    needs_human: shouldEscalate || isShadow,
    prompt_tokens: llmResp.usage?.prompt_tokens || 0,
    completion_tokens: llmResp.usage?.completion_tokens || 0,
    latency_ms: Date.now() - event.started_at
  }
};
